# Print the rest if truncated
if len(orders_out) > 5000:
    print(orders_out[5000:10000])

# Parse the order data to find the relevant items
import json, re

# Extract JSON blocks from the output
json_blocks = re.findall(r'\{[\s\S]*?\n\}', orders_out)
orders_data = []
for block in json_blocks:
    try:
        parsed = json.loads(block)
        if "order_id" in parsed:
            orders_data.append(parsed)
    except:
        pass

print(f"Parsed {len(orders_data)} orders")
for o in orders_data:
    print(f"\nOrder: {o['order_id']}, Status: {o['status']}")
    for item in o.get('items', []):
        print(f"  Item: {item}")
    print(f"  Payment: {o.get('payment_history', [])}")

